// Custom FPS and Ping Display
let statsDiv = document.createElement('div');
statsDiv.id = 'customStatsDisplay';
statsDiv.style.position = 'absolute';
statsDiv.style.top = '15px';
statsDiv.style.left = '15px';
statsDiv.style.color = '#00FF00';
statsDiv.style.fontSize = '16px';
statsDiv.style.fontFamily = 'Hammersmith One, sans-serif';
statsDiv.style.textShadow = '2px 2px 3px #000';
statsDiv.style.pointerEvents = 'none';
statsDiv.style.zIndex = '9999';
document.body.appendChild(statsDiv);

let frames = 0;
let lastTime = performance.now();
let currentFps = 0;

function updateStats() {
    frames++;
    let now = performance.now();
    if (now - lastTime >= 1000) {
        currentFps = frames;
        frames = 0;
        lastTime = now;
    }
    let ping = window.pingTime || 0;
    let popStr = "";
    try {
        const pop = window._novaServerPop && window._novaServerPop();
        if (typeof pop === "number" && pop > 0) {
            popStr = ` <span style="color:#FFF;">|</span> Players: <span style="color:#ffcc00;">${pop}</span>`;
        }
    } catch (e) {}
    let botStr = "";
    try {
        if (window.RynBots && window.RynBots.list && window.RynBots.list.length) {
            const c = window.RynBots.counts();
            // "ready" = bots connected and waiting to drop (Hold mode); also show
            // how many are already in-game, and any still connecting.
            botStr = ` <span style="color:#FFF;">|</span> Bots: <span style="color:#00e5ff;">${c.waiting} ready</span>`;
            if (c.ingame) botStr += ` / ${c.ingame} in`;
            if (c.connecting) botStr += ` / ${c.connecting}…`;
            // Scan and Kill / possession state, so you never have to guess what
            // the swarm is currently doing.
            const h = window.RynBots.hunt;
            if (h) {
                botStr += h.foundBy
                    ? ` <span style="color:#FFF;">|</span> <span style="color:#ff3b30;">SPOTTED ${h.name || h.raw}</span>`
                    : ` <span style="color:#FFF;">|</span> <span style="color:#ffcc00;">hunting ${h.name || h.raw}…</span>`;
            }
            if (window.RynBots.ceasefire) botStr += ` <span style="color:#FFF;">|</span> <span style="color:#9aa0a6;">ceasefire</span>`;
            const pb = window.RynBots.possessed;
            if (pb) botStr += ` <span style="color:#FFF;">|</span> <span style="color:#00e5ff;">▶ ${pb.name}</span>`;
        }
    } catch (e) {}
    statsDiv.innerHTML = `FPS: ${currentFps} <span style="color:#FFF;">|</span> Ping: ${ping}ms${popStr}${botStr}`;
    requestAnimationFrame(updateStats);
}
requestAnimationFrame(updateStats);
