        // INPUT UTILS:
        function getMoveDir() {
            var dx = 0;
            var dy = 0;
            if (controllingTouch.id != -1) {
                dx += controllingTouch.currentX - controllingTouch.startX;
                dy += controllingTouch.currentY - controllingTouch.startY;
            } else {
                for (var key in moveKeys) {
                    var tmpDir = moveKeys[key];
                    dx += !!keys[key] * tmpDir[0];
                    dy += !!keys[key] * tmpDir[1];
                }
            }
            return (dx == 0 && dy == 0) ? undefined : UTILS.fixTo(Math.atan2(dy, dx), 2);
        }
        var lastDir;
        let lessDir = undefined;
        let tmpAttackDir = undefined;
        let plusDir = 0;
        function getAttackDir() {
            if (myPlayer) {
                if (autoaim && nearestEnemy) {
                    return autoaimAngle;
                }

                if (antiPush) {
                    return antiPushAngle;
                }

                if (autoBreak) {
                    return autoBreakAngle;
                }

                if (gatherGrind && grindAngle) {
                    return grindAngle;
                }


                // A bot has no mouse. Once the mod's own overrides above have
                // had their say, the bot's aim is whoever it is fighting, and
                // failing that the way it is already facing.
                if (inBotCtx()) {
                    // Driving this one? Then the mouse IS its aim, exactly as
                    // it is yours when you are in your own body.
                    try {
                        if (RynBots.possessed === botCtx) {
                            return UTILS.fixTo(Math.atan2(mouseY - (screenHeight / 2),
                                                          mouseX - (screenWidth / 2)), 2);
                        }
                    } catch (e) {}
                    if (nearestEnemy) {
                        return UTILS.fixTo(Math.atan2(nearestEnemy.y2 - myPlayer.y2,
                                                      nearestEnemy.x2 - myPlayer.x2), 2);
                    }
                    return UTILS.fixTo(myPlayer.d2 === undefined ? (myPlayer.dir || 0) : myPlayer.d2, 2);
                }

                // While you are inside a bot the mouse belongs to the bot. Your
                // own body keeps the angle it had, so it stays put instead of
                // spinning to follow a cursor that is no longer aiming it.
                if (RynBots.possessed) return UTILS.fixTo(lastDir || 0, 2);

                if (!myPlayer.lockDir && !usingTouch) {
                    lastDir = Math.atan2(mouseY - (screenHeight / 2), mouseX - (screenWidth / 2));
                    return UTILS.fixTo(lastDir || 0, 2);
                }
            }

            return 0;
        }

        // KEYS:
        var keys = {};
        var moveKeys = {
            87: [0, -1],
            38: [0, -1],
            83: [0, 1],
            40: [0, 1],
            65: [-1, 0],
            37: [-1, 0],
            68: [1, 0],
            39: [1, 0]
        };
        function resetMoveDir() {
            keys = {};
            io.send("e");
        }
        function keysActive() {
            return (allianceMenu.style.display != "block"
                    && chatHolder.style.display != "block"
                    // Typing to the Pod must not drive the character.
                    && !(window.Pod && document.activeElement === window.Pod._input));
        }
        let killCount = 0;
        let killedName = "Unknown"; for (let i = 0; i < players.length; i++) { let p = players[i]; if (p && p.sid !== myPlayer.sid && !isAlly(p.sid) && p.health <= 0) { killedName = p.name; break; } }
        function showKillMessage(victimName) {
            killCount++;
            const messageDiv = document.createElement('div');
            messageDiv.textContent = `${killedName} has died.`;

            Object.assign(messageDiv.style, {
                position: "fixed",
                top: "1200px",
                left: "65%",
                transform: "translateX(-50%) translateY(-50px)",
                backgroundColor: "#1a1a1a",
                backgroundImage: "linear-gradient(to right, rgba(20, 20, 20, 0.95), rgba(40, 40, 40, 0.95))",
                color: "#ffffff",
                padding: "10px 25px",
                borderRadius: "15px",
                fontSize: "1.1rem",
                fontWeight: "bold",
                letterSpacing: "1px",
                textShadow: "0 0 5px rgba(255,255,255,0.7)",
                zIndex: "1000",
                boxShadow: "0 8px 20px rgba(0, 0, 0, 0.8), inset 0 0 10px rgba(0, 0, 0, 0.9), 0 0 15px rgba(50, 50, 50, 0.9)",
                border: "2px solid rgba(100, 100, 100, 0.5)",
                opacity: "0",
                transition: "opacity 0.6s ease-out, transform 0.6s ease-out",
                willChange: "opacity, transform"
            });
            document.body.appendChild(messageDiv);

            requestAnimationFrame(() => {
                messageDiv.style.opacity = "1";
                messageDiv.style.transform = "translateX(-50%) translateY(0)";
            });

            setTimeout(() => {
                messageDiv.style.opacity = "0";
                messageDiv.style.transform = "translateX(-50%) translateY(-50px)";
                messageDiv.addEventListener("transitionend", () => {
                    if (messageDiv.parentNode) {
                        messageDiv.parentNode.removeChild(messageDiv);
                    }
                }, { once: true });
            }, 2500);
        }

        // Repeat guard for the bot-control arrows, kept apart from `keys` so a
        // held arrow never doubles as a movement key.
        const possessKeys = {};
        function keyDown(event) {
            let keyStr = event.code;
            if (keyStr.startsWith("Key")) keyStr = keyStr.slice(3);
            if (keyStr.startsWith("Digit")) keyStr = keyStr.slice(5);
            keyStr = keyStr.toUpperCase();
            var keyNum = event.which || event.keyCode || 0;
            if (keyNum == 27) {
                if (!keys[keyNum]) {
                    keys[keyNum] = 1;
                    if (myPlayer && myPlayer.alive) {
                        hideAllWindows();
                        $("#modMenus").toggle();
                    }
                }
            } else if (myPlayer && myPlayer.alive && keysActive()) {
                // Bot control: left steps to the next bot, right to the one
                // before it, up hands you back your own character. The arrows
                // stop steering you while this is on — that is the trade, and
                // the toggle in Bots -> Control turns it off.
                // The repeat guard lives in its own map, never in `keys` — an
                // arrow parked in `keys` is an arrow the movement code reads as
                // "walking that way".
                if (window.vars.botPossessKeys && (keyNum == 37 || keyNum == 39 || keyNum == 38)) {
                    event.preventDefault();
                    if (!possessKeys[keyNum]) {
                        possessKeys[keyNum] = 1;
                        try {
                            if (keyNum == 38) RynBots.release();
                            else RynBots.possess(keyNum == 37 ? 1 : -1);
                        } catch (e) {}
                    }
                    return;
                }
                if (!keys[keyNum]) {
                    keys[keyNum] = 1;
                    // While you are inside a bot the number row is the bot's
                    // action bar, not yours.
                    if (RynBots.possessed && keyNum >= 49 && keyNum <= 57
                        && RynBots.possessSlot(keyNum - 49)) {
                        return;
                    }
                    if (keyNum == 69) {
                        ePress = !ePress;
                    } else if (keyNum == 67) {
                        updateMapMarker();
                    } else if (keyNum == 88) {
                        sendLockDir();
                    } else if (myPlayer.weapons[keyNum - 49] != undefined) {
                        keyCodeWeapon = myPlayer.weapons[keyNum - 49];
                    } else if (myPlayer.items[keyNum - 49 - myPlayer.weapons.length] != undefined) {
                        selectToBuild(myPlayer.items[keyNum - 49 - myPlayer.weapons.length]);
                    } else if (keyNum == 82) {
                        sendMapPing();
                    } else if (keyNum == 32) {
                        attackState = 1;
                        sendAtckState();
                    } else if (keyStr === window.vars.keyAutoMills) {
                        autoMills = !autoMills;
                    } else if (keyNum == 81) {
                        qPress = true;
                    } else if (keyStr === window.vars.keyAutoGrind) {
                        gPressed = !gPressed;
                    } else if (keyStr === window.vars.keyPlaceSpike) {
                        spikePress = true;
                    } else if (keyStr === window.vars.keyPlaceTrap) {
                        trapPress = true;
                    } else if (keyStr === window.vars.keyPlaceTurret) {
                        turretPress = true;
                    }
                    else if (keyStr === window.vars.keyPathBreak) {
                        pathBreak = !pathBreak
                    }
                    else if (keyStr === window.vars.keyVelocityTick) {
                        window.vars.velocityTick = !window.vars.velocityTick;
                    }
                    else if (keyStr === window.vars.keyPlacers) {
                        // One key toggles Auto Place + Preplace + Replace together:
                        // if any is off, turn all on; otherwise turn all off.
                        const on = !(window.vars.autoPlace && window.vars.prePlace && window.vars.replace);
                        window.vars.autoPlace = on;
                        window.vars.prePlace = on;
                        window.vars.replace = on;
                    }
                    else if (keyStr === window.vars.keySpawnBot) {
                        RynBots.spawn(window.vars.botCount);
                    }
                    else if (keyStr === window.vars.keyKillBots) {
                        RynBots.killAll();
                    }
                    else if (keyStr === window.vars.keyReleaseBots) {
                        RynBots.releaseAll();
                    }
                    else if (keyStr === window.vars.keyBotFreeze) {
                        // Freeze Bot — every bot nailed to the ground until the
                        // key is pressed again.
                        RynBots.toggleFreeze();
                    }
                    else if (keyStr === window.vars.keyBotAttack) {
                        // Manual swing key: only does anything while Sync is off,
                        // and the bots swing for as long as it is held.
                        RynBots.setManualAttack(true);
                    }
                    else if (keyStr === window.vars.keyPacketSpam) {
                        window.vars.botPacketSpam = !window.vars.botPacketSpam;
                        try { if (typeof addChatLog === "function")
                            addChatLog("Packet Spam " + (window.vars.botPacketSpam ? "ON" : "OFF"), "#00e5ff"); } catch (e) {}
                    }
                    else if (keyStr === window.vars.keyPodChat) {
                        try { Pod.toggle(); } catch (e) {}
                    }
                    else if (keyStr === window.vars.keyPause) {
                        try { if (window.YoRHaFX) window.YoRHaFX.pauseToggle(); } catch (e) {}
                    }
                }
            }
        }
        window.addEventListener('keydown', UTILS.checkTrusted(keyDown));
        function keyUp(event) {
            let keyStr = event.code;
            if (keyStr.startsWith("Key")) keyStr = keyStr.slice(3);
            if (keyStr.startsWith("Digit")) keyStr = keyStr.slice(5);
            keyStr = keyStr.toUpperCase();
            if (myPlayer && myPlayer.alive) {
                var keyNum = event.which || event.keyCode || 0;
                if (possessKeys[keyNum]) possessKeys[keyNum] = 0;
                if (keyNum == 13) {
                    toggleChat();
                } else if (keysActive()) {
                    if (keys[keyNum]) {
                        keys[keyNum] = 0;
                        if (keyNum == 32) {
                            attackState = 0;
                            sendAtckState();
                        } else if (keyNum == 81) {
                            qPress = true;
                        }
                        else if(keyStr === window.vars.keyPlaceSpike) {
                            spikePress = false;
                        }
                        else if(keyStr === window.vars.keyPlaceTrap) {
                            trapPress = false;
                        }
                        else if(keyStr === window.vars.keyPlaceTurret) {
                            turretPress = false;
                        }
                        else if (keyStr === window.vars.keyBotAttack) {
                            RynBots.setManualAttack(false);
                        }
                    }
                }
            }
        }
        window.addEventListener('keyup', UTILS.checkTrusted(keyUp));
        // While you are inside a bot, push the new input straight down its
