        // ICONS:
        var iconSprites = {};
        var icons = ["crown", "skull"];
        function loadIcons() {
            for (var i = 0; i < icons.length; ++i) {
                var tmpSprite = new Image();
                tmpSprite.onload = function () {
                    this.isLoaded = true;
                };
                tmpSprite.src = ".././img/icons/" + icons[i] + ".png";
                iconSprites[icons[i]] = tmpSprite;
            }
        }

        // UPDATE UPGRADES:
        var tmpList = [];
        function updateUpgrades(points, age) {
            myPlayer.upgradePoints = points;
            myPlayer.upgrAge = age;
            if (points > 0) {
                tmpList.length = 0;
                UTILS.removeAllChildren(upgradeHolder);
                for (var i = 0; i < items.weapons.length; ++i) {
                    if (items.weapons[i].age == age && (items.weapons[i].pre == undefined || myPlayer.weapons.indexOf(items.weapons[i].pre) >= 0)) {
                        var e = UTILS.generateElement({
                            id: "upgradeItem" + i,
                            class: "actionBarItem",
                            onmouseout: function () { showItemInfo(); },
                            parent: upgradeHolder
                        });
                        e.style.backgroundImage = document.getElementById("actionBarItem" + i).style.backgroundImage;
                        tmpList.push(i);
                    }
                }
                for (var i = 0; i < items.list.length; ++i) {
                    if (items.list[i].age == age && (items.list[i].pre == undefined || myPlayer.items.indexOf(items.list[i].pre) >= 0)) {
                        var tmpI = (items.weapons.length + i);
                        var e = UTILS.generateElement({
                            id: "upgradeItem" + tmpI,
                            class: "actionBarItem",
                            onmouseout: function () { showItemInfo(); },
                            parent: upgradeHolder
                        });
                        e.style.backgroundImage = document.getElementById("actionBarItem" + tmpI).style.backgroundImage;
                        tmpList.push(tmpI);
                    }
                }
                for (var i = 0; i < tmpList.length; i++) {
                    (function (i) {
                        var tmpItem = document.getElementById('upgradeItem' + i);
                        tmpItem.onmouseover = function () {
                            if (items.weapons[i]) {
                                showItemInfo(items.weapons[i], true);
                            } else {
                                showItemInfo(items.list[i - items.weapons.length]);
                            }
                        };
                        tmpItem.onclick = UTILS.checkTrusted(function () {
                            io.send("H", i);
                        });
                        UTILS.hookTouchEvents(tmpItem);
                    })(tmpList[i]);
                }
                if (tmpList.length) {
                    upgradeHolder.style.display = "block";
                    upgradeCounter.style.display = "block";
                    upgradeCounter.innerHTML = "SELECT ITEMS (" + points + ")";
                } else {
                    upgradeHolder.style.display = "none";
                    upgradeCounter.style.display = "none";
                    showItemInfo();
                }
            } else {
                upgradeHolder.style.display = "none";
                upgradeCounter.style.display = "none";
                showItemInfo();
            }
        }
        function sendUpgrade(index) {
            if (actAsBot("H", index)) return;
            io.send("H", index);
        }

        // UPDATE AGE:
        function updateAge(xp, mxp, age) {
            if (xp != undefined) myPlayer.XP = xp;
            if (mxp != undefined) myPlayer.maxXP = mxp;
            if (age != undefined) myPlayer.age = age;

            age == config.maxAge ? (ageText.innerHTML = "MAX AGE",
                                    ageBarBody.style.width = "100%") : (ageText.innerHTML = "AGE " + myPlayer.age,
                                                                        ageBarBody.style.width = myPlayer.XP / myPlayer.maxXP * 100 + "%")
            /*
                if (age == config.maxAge) {
                    ageText.innerHTML = "MAX AGE";
                } else {
                    ageText.innerHTML = "AGE " + player.age;
                }
                */
        }

        // UPDATE LEADERBOARD:
        function updateLeaderboard(data) {
            UTILS.removeAllChildren(leaderboardData);
            var tmpC = 1;
            for (var i = 0; i < data.length; i += 3) {
                (function (i) {
                    UTILS.generateElement({
                        class: "leaderHolder",
                        parent: leaderboardData,
                        children: [
                            UTILS.generateElement({
                                class: "leaderboardItem",
                                style: "color:" + ((data[i] == myPlayerSID) ? "#fff" : "rgba(255,255,255,0.6)"),
                                text: tmpC + ". " + (data[i + 1] != "" ? data[i + 1] : "unknown")
                            }),
                            UTILS.generateElement({
                                class: "leaderScore",
                                text: UTILS.kFormat(data[i + 2]) || "0"
                            })
                        ]
                    });
                })(i);
                tmpC++;
            }
        }

        // UPDATE GAME:
        function updateGame() {
            if (true) {

                // UPDATE DIRECTION:
                /*
                    if (player) {
                        if (!lastSent || now - lastSent >= (1000 / config.clientSendRate)) {
                            lastSent = now;
                            let atckDir = getAttackDir();
                            if (lessDir !== atckDir) {
                                lessDir = atckDir;
                                io.send("D", atckDir);
                            }
                            tmpAttackDir = atckDir;
                        }
                    }
                    */

                // DEATH TEXT:
                if (deathTextScale < 120) {
                    deathTextScale += 0.1 * delta;
                    diedText.style.fontSize = Math.min(Math.round(deathTextScale), 120) + "px";
                }

                // MOVE CAMERA:
                // While you are possessing a bot the camera rides the bot. Its
                // position comes off its own socket, so it is exact even when
                // the bot is far outside anything your own client can see.
                let camBot = null;
                try { if (RynBots.possessed && RynBots.possessed.alive) camBot = RynBots.possessed; } catch (e) {}
                if (camBot) {
                    let tmpDist = UTILS.getDistance(camX, camY, camBot.x, camBot.y);
                    let tmpDir = UTILS.getDirection(camBot.x, camBot.y, camX, camY);
                    // Snap rather than glide when the jump is a whole screen or
                    // more — that is a bot switch, not a walk.
                    if (tmpDist > 1200) {
                        camX = camBot.x;
                        camY = camBot.y;
                    } else if (tmpDist > 0.05) {
                        let camSpd = Math.min(tmpDist * 0.0093 * delta, tmpDist);
                        camX += camSpd * Math.cos(tmpDir);
                        camY += camSpd * Math.sin(tmpDir);
                    }
                } else if (myPlayer) {
                    let tmpDist = UTILS.getDistance(camX, camY, myPlayer.x, myPlayer.y);
                    let tmpDir = UTILS.getDirection(myPlayer.x, myPlayer.y, camX, camY);
                    let camSpd = Math.min(tmpDist * 0.0093 * delta, tmpDist);
                    if (tmpDist > 0.05) {
                        camX += camSpd * Math.cos(tmpDir);
                        camY += camSpd * Math.sin(tmpDir);
                    } else {
                        camX = myPlayer.x;
                        camY = myPlayer.y;
                    }
                } else {
                    camX = config.mapScale / 2 + config.riverWidth;
                    camY = config.mapScale / 2;
                }

                // INTERPOLATE PLAYERS AND AI:
                let lastTime = now - (1000 / config.serverUpdateRate);
                let tmpDiff;
                // Interpolate whichever world is on screen — without this the
                // bot's view would jump a whole server tick at a time.
                const interpPlayers = renderPlayerSource();
                const interpAis = renderAiSource();
                for (let i = 0; i < interpPlayers.length + interpAis.length; ++i) {
                    tmpObj = interpPlayers[i] || interpAis[i - interpPlayers.length];
                    if (tmpObj && tmpObj.visible) {
                        if (tmpObj.forcePos) {
                            tmpObj.x = tmpObj.x2;
                            tmpObj.y = tmpObj.y2;
                            tmpObj.dir = tmpObj.d2;
                        } else {
                            let total = tmpObj.t2 - tmpObj.t1;
                            let fraction = lastTime - tmpObj.t1;
                            let ratio = (fraction / total);
                            let rate = 170;
                            tmpObj.dt += delta;
                            let tmpRate = Math.min(1.7, tmpObj.dt / rate);
                            tmpDiff = (tmpObj.x2 - tmpObj.x1);
                            tmpObj.x = tmpObj.x1 + (tmpDiff * tmpRate);
                            tmpDiff = (tmpObj.y2 - tmpObj.y1);
                            tmpObj.y = tmpObj.y1 + (tmpDiff * tmpRate);
                            tmpObj.dir = Math.lerpAngle(tmpObj.d2, tmpObj.d1, Math.min(1.2, ratio));
                        }
                    }
                }

                // RENDER CORDS:
                xOffset = camX - (maxScreenWidth / 2);
                yOffset = camY - (maxScreenHeight / 2);

                // RENDER BACKGROUND:
                // YoRHa Visual repaints every biome in the muted parchment
                // palette; off, the game's own greens and sand.
                const GRASS = "#b6db66";
                const SAND  = "#dbc666";
                const SNOW  = "#fff";
                if (config.snowBiomeTop - yOffset <= 0 && config.mapScale - config.snowBiomeTop - yOffset >= maxScreenHeight) {
                    mainContext.fillStyle = GRASS;
                    mainContext.fillRect(0, 0, maxScreenWidth, maxScreenHeight);
                } else if (config.mapScale - config.snowBiomeTop - yOffset <= 0) {
                    mainContext.fillStyle = SAND;
                    mainContext.fillRect(0, 0, maxScreenWidth, maxScreenHeight);
                } else if (config.snowBiomeTop - yOffset >= maxScreenHeight) {
                    mainContext.fillStyle = SNOW;
                    mainContext.fillRect(0, 0, maxScreenWidth, maxScreenHeight);
                } else if (config.snowBiomeTop - yOffset >= 0) {
                    mainContext.fillStyle = SNOW;
                    mainContext.fillRect(0, 0, maxScreenWidth, config.snowBiomeTop - yOffset);
                    mainContext.fillStyle = GRASS;
                    mainContext.fillRect(0, config.snowBiomeTop - yOffset, maxScreenWidth,
                                         maxScreenHeight - (config.snowBiomeTop - yOffset));
                } else {
                    mainContext.fillStyle = GRASS;
                    mainContext.fillRect(0, 0, maxScreenWidth,
                                         (config.mapScale - config.snowBiomeTop - yOffset));
                    mainContext.fillStyle = SAND;
                    mainContext.fillRect(0, (config.mapScale - config.snowBiomeTop - yOffset), maxScreenWidth,
                                         maxScreenHeight - (config.mapScale - config.snowBiomeTop - yOffset));
                }

                // RENDER WATER AREAS:
                if (!firstSetup) {
                    waterMult += waterPlus * config.waveSpeed * delta;
                    if (waterMult >= config.waveMax) {
                        waterMult = config.waveMax;
                        waterPlus = -1;
                    } else if (waterMult <= 1) {
                        waterMult = waterPlus = 1;
                    }
                    mainContext.globalAlpha = 1;
                    mainContext.fillStyle = "#dbc666";
                    renderWaterBodies(xOffset, yOffset, mainContext, config.riverPadding);
                    mainContext.fillStyle = "#91b2db";
                    renderWaterBodies(xOffset, yOffset, mainContext, (waterMult - 1) * 250);
                }

                // RENDER GRID:
                /*
                    mainContext.lineWidth = 4;
                    mainContext.strokeStyle = "#000";
                    mainContext.globalAlpha = 0.06;
                    mainContext.beginPath();
                    for (var x = -camX; x < maxScreenWidth; x += maxScreenHeight / 18) {
                        if (x > 0) {
                            mainContext.moveTo(x, 0);
                            mainContext.lineTo(x, maxScreenHeight);
                        }
                    }
                    for (var y = -camY; y < maxScreenHeight; y += maxScreenHeight / 18) {
                        if (x > 0) {
                            mainContext.moveTo(0, y);
                            mainContext.lineTo(maxScreenWidth, y);
                        }
                    }
                    mainContext.stroke();
                    */

                // RENDER BOTTOM LAYER:
                mainContext.globalAlpha = 1;
                mainContext.strokeStyle = outlineColor;
                renderGameObjects(-1, xOffset, yOffset);

                // RENDER PROJECTILES:
                mainContext.globalAlpha = 1;
                mainContext.lineWidth = outlineWidth;
                renderProjectiles(0, xOffset, yOffset);

                // RENDER VELOCITY POSITION
                /*
                    if(myPlayer && myPlayer.alive){
                        mainContext.globalAlpha = 0.5;

                        mainContext.save();
                        mainContext.translate(myPlayer.xVel - xOffset, myPlayer.yVel - yOffset);

                        mainContext.rotate(myPlayer.dir);
                        renderPlayer(myPlayer, mainContext);
                        mainContext.restore();

                        mainContext.globalAlpha = 1;
                    }
                    */



                // RENDER PLAYERS:
                renderPlayers(xOffset, yOffset, 0);

                // RENDER AI:
                mainContext.globalAlpha = 1;
                const aiList = renderAiSource();
                for (var i = 0; i < aiList.length; ++i) {
                    tmpObj = aiList[i];
                    if (tmpObj.active && tmpObj.visible) {
                        tmpObj.animate(delta);
                        mainContext.save();
                        mainContext.translate(tmpObj.x - xOffset, tmpObj.y - yOffset);
                        mainContext.rotate(tmpObj.dir + tmpObj.dirPlus - (Math.PI / 2));
                        renderAI(tmpObj, mainContext);
                        mainContext.restore();
                    }
                }

                // RENDER GAME OBJECTS (LAYERED):
                renderGameObjects(0, xOffset, yOffset);
                renderProjectiles(1, xOffset, yOffset);
                renderGameObjects(1, xOffset, yOffset);
                renderPlayers(xOffset, yOffset, 1);
                renderGameObjects(2, xOffset, yOffset);
                renderGameObjects(3, xOffset, yOffset);

                // THE POD — follows the camera's player, paints the aim line.
                try { renderPod(xOffset, yOffset); } catch (e) {}

                // MAP BOUNDARIES:
                mainContext.fillStyle = "#000";
                mainContext.globalAlpha = 0.09;
                if (xOffset <= 0) {
                    mainContext.fillRect(0, 0, -xOffset, maxScreenHeight);
                } if (config.mapScale - xOffset <= maxScreenWidth) {
                    var tmpY = Math.max(0, -yOffset);
                    mainContext.fillRect(config.mapScale - xOffset, tmpY, maxScreenWidth - (config.mapScale - xOffset), maxScreenHeight - tmpY);
                } if (yOffset <= 0) {
                    mainContext.fillRect(-xOffset, 0, maxScreenWidth + xOffset, -yOffset);
                } if (config.mapScale - yOffset <= maxScreenHeight) {
                    var tmpX = Math.max(0, -xOffset);
                    var tmpMin = 0;
                    if (config.mapScale - xOffset <= maxScreenWidth)
                        tmpMin = maxScreenWidth - (config.mapScale - xOffset);
                    mainContext.fillRect(tmpX, config.mapScale - yOffset,
                                         (maxScreenWidth - tmpX) - tmpMin, maxScreenHeight - (config.mapScale - yOffset));
                }

                renderEnemyTraps(xOffset, yOffset);
                for (let object of predictObjects) {
                    mainContext.globalAlpha = .6;

                    mainContext.save();
                    mainContext.translate(object.x - xOffset, object.y - yOffset);

                    let image = getItemSprite({ id: object.id, name: object.name, scale: object.scale, prediction: true, preplace: object.preplace });
                    mainContext.drawImage(image, -(image.width / 2), -(image.height / 2));

                    mainContext.rotate(object.angle);
                    mainContext.restore();
                }

                for(let i in visibleObjects){
                    let object = visibleObjects[i];
                    if(UTILS.getDistance(myPlayer.x, myPlayer.y, object.x, object.y) < 300 && object.isItem){
                        let radius = object.id > 5 && object.id < 10 ? 33 : 22;
                        let healthArc = object.health * (Math.PI * 2 / object.maxHealth);
                        let color = object.owner.sid == myPlayer.sid ? "#e9b3e9" : isAlly(object.owner.sid) ? "0000FF" : "#ff0000";

                        mainContext.globalAlpha = 1;
                        mainContext.lineCap = "round";
                        mainContext.strokeStyle = darkOutlineColor;
                        mainContext.lineWidth = 12.5;
                        mainContext.beginPath();
                        mainContext.arc(object.x - xOffset, object.y - yOffset, radius, 0, healthArc);
                        mainContext.stroke();

                        mainContext.strokeStyle = color;
                        mainContext.lineWidth = 5;
                        mainContext.beginPath();
                        mainContext.arc(object.x - xOffset, object.y - yOffset, radius, 0, healthArc);
                        mainContext.stroke();
                    }
                }
                // RENDER DAY/NIGHT TIME (Dark Black Vignette)

                mainContext.globalAlpha = 1;
                const gradient = mainContext.createRadialGradient(
                    maxScreenWidth / 2, maxScreenHeight / 2, 0,
                    maxScreenWidth / 2, maxScreenHeight / 2, maxScreenWidth / 2 );
                // pure black instead of blue
                gradient.addColorStop(0, "rgba(0, 0, 00, 0.10)");
                gradient.addColorStop(0.5, "rgba(0, 0, 00, 0.20)");
                gradient.addColorStop(1, "rgba(0, 0, 00, 0.30)");
                mainContext.fillStyle = gradient;
                mainContext.fillRect(0, 0, maxScreenWidth, maxScreenHeight);

                // YoRHa ATMOSPHERE — a full-screen mood wash only. It NEVER
                // touches any object's shape, size, or position, so every
                // hitbox reads exactly where it looks. Just a parchment
                // color-grade, a warm vignette, and faint horizontal
                // scanlines for the NieR:Automata terminal feel.
                if (yorhaOn()) {
                    mainContext.save();
                    // Parchment/sand multiply wash across the whole frame.
                    mainContext.globalCompositeOperation = "multiply";
                    mainContext.globalAlpha = 0.22;
                    mainContext.fillStyle = "#c9c3a8";
                    mainContext.fillRect(0, 0, maxScreenWidth, maxScreenHeight);
                    // A little warmth lifted back in so it doesn't go grey.
                    mainContext.globalCompositeOperation = "overlay";
                    mainContext.globalAlpha = 0.10;
                    mainContext.fillStyle = "#efe9d0";
                    mainContext.fillRect(0, 0, maxScreenWidth, maxScreenHeight);
                    // Warm ink vignette hugging the edges.
                    mainContext.globalCompositeOperation = "source-over";
                    const yGrad = mainContext.createRadialGradient(
                        maxScreenWidth / 2, maxScreenHeight / 2, maxScreenHeight * 0.35,
                        maxScreenWidth / 2, maxScreenHeight / 2, maxScreenWidth * 0.62);
                    yGrad.addColorStop(0, "rgba(47,44,38,0)");
                    yGrad.addColorStop(1, "rgba(47,44,38,0.34)");
                    mainContext.globalAlpha = 1;
                    mainContext.fillStyle = yGrad;
                    mainContext.fillRect(0, 0, maxScreenWidth, maxScreenHeight);
                    // Faint scanlines.
                    mainContext.globalAlpha = 0.05;
                    mainContext.fillStyle = "#2f2c26";
                    for (var ySL = 0; ySL < maxScreenHeight; ySL += 3) {
                        mainContext.fillRect(0, ySL, maxScreenWidth, 1);
                    }
                    mainContext.restore();
                    mainContext.globalAlpha = 1;
                }



                // FROM HERE

                // BUILDING HEALTH  (Falcon 0.4.7's renderBuildingHealth)
                //
                // Drawn after every object layer and before the player labels,
                // where Falcon has it, so a bar never hides under the building
                // it belongs to. Only damaged buildings get one — an untouched
                // wall would just be clutter — and only within 400, which is
                // the range the rest of the mod already reasons about.
                //
                // YoRHa's GameObject carries health and maxHealth already, and
                // changeObjectHealth() keeps health current off the hit
                // packets, so this reads what the mod already knows: whether
                // one more swing takes that trap down.
                if (visualOn("buildingHealth") && myPlayer) try {
                    mainContext.globalAlpha = 1;
                    const healthObjects = renderObjectSource();
                    for (var i = 0; i < healthObjects.length; ++i) {
                        const building = healthObjects[i];
                        if (!building.active || !building.isItem || !building.owner) continue;
                        if (!building.maxHealth || building.health >= building.maxHealth) continue;
                        if (UTILS.getDistance(building.x, building.y, myPlayer.x2, myPlayer.y2) > 400) continue;

                        const barX = building.x + building.xWiggle - xOffset - (config.healthBarWidth / 2);
                        const barY = building.y + building.yWiggle - yOffset;

                        mainContext.fillStyle = darkOutlineColor;
                        mainContext.roundRect(barX - config.healthBarPad, barY - config.healthBarPad,
                                              config.healthBarWidth + (config.healthBarPad * 2), 17, 8);
                        mainContext.fill();

                        mainContext.fillStyle = building.owner.sid == myPlayer.sid ? "#8ecc51" :
                                                isAlly(building.owner.sid) ? "#e0c655" : "#cc5151";
                        mainContext.roundRect(barX, barY,
                                              config.healthBarWidth * (Math.max(0, building.health) / building.maxHealth),
                                              17 - (config.healthBarPad * 2), 7);
                        mainContext.fill();
                    }
                } catch (e) {}

                // RENDER PLAYER AND AI UI / PLAYERINFOS:
                // Names, health bars and crowns follow whichever world is on
                // screen, so the bot's view is labelled like the real thing.
                mainContext.strokeStyle = darkOutlineColor;
                const uiPlayers = renderPlayerSource(), uiAis = renderAiSource();
                for (var i = 0; i < uiPlayers.length + uiAis.length; ++i) {
                    tmpObj = uiPlayers[i] || uiAis[i - uiPlayers.length];
                    if (tmpObj.visible) {

                        // NAME AND HEALTH:
                        if (tmpObj.skinIndex != 10 || (tmpObj == myPlayer) || (tmpObj.team && tmpObj.team == myPlayer.team)) {
                            var tmpText = (tmpObj.team ? `[${tmpObj.team}] ` : ``) + (tmpObj.name || ``);
                            if (tmpText != "") {
                                mainContext.font = (tmpObj.nameScale || 30) + "px " + (yorhaOn() ? "Jost, 'Hammersmith One'" : "Hammersmith One");
                                mainContext.fillStyle = "#fff";
                                mainContext.textBaseline = "middle";
                                mainContext.textAlign = "center";
                                mainContext.lineWidth = (tmpObj.nameScale ? 11 : 8);
                                mainContext.lineJoin = "round";
                                mainContext.strokeText(tmpText, tmpObj.x - xOffset, (tmpObj.y - yOffset - tmpObj.scale) - config.nameY);
                                mainContext.fillText(tmpText, tmpObj.x - xOffset, (tmpObj.y - yOffset - tmpObj.scale) - config.nameY);
                                if (tmpObj.isLeader && iconSprites["crown"].isLoaded) {
                                    var tmpS = config.crownIconScale;
                                    var tmpX = tmpObj.x - xOffset - (tmpS / 2) - (mainContext.measureText(tmpText).width / 2) - config.crownPad;
                                    mainContext.drawImage(iconSprites["crown"], tmpX, (tmpObj.y - yOffset - tmpObj.scale)
                                                          - config.nameY - (tmpS / 2) - 5, tmpS, tmpS);
                                } if (tmpObj.iconIndex == 1 && iconSprites["skull"].isLoaded) {
                                    var tmpS = config.crownIconScale;
                                    var tmpX = tmpObj.x - xOffset - (tmpS / 2) + (mainContext.measureText(tmpText).width / 2) + config.crownPad;
                                    mainContext.drawImage(iconSprites["skull"], tmpX, (tmpObj.y - yOffset - tmpObj.scale)
                                                          - config.nameY - (tmpS / 2) - 5, tmpS, tmpS);
                                }
                            }


                            if (tmpObj.isPlayer && tmpObj.alive && tmpObj.shameCount !== undefined) {
                                const centerX = tmpObj.x - xOffset;
                                const centerY = tmpObj.y - yOffset;
                                const playerTop = centerY - tmpObj.scale;
                                const hpBarY = playerTop + 120;
                                const shameY = hpBarY + 12;
                                mainContext.save();
                                mainContext.font = "bold 16px Hammersmith One";
                                mainContext.textAlign = "center";
                                mainContext.textBaseline = "middle";
                                mainContext.lineJoin = "round";
                                mainContext.lineWidth = 5;
                                mainContext.strokeStyle = "#000000";
                                mainContext.strokeText(tmpObj.shameCount, centerX, shameY);
                                mainContext.fillStyle = "#ff8c42";
                                mainContext.fillText(tmpObj.shameCount, centerX, shameY);
                                mainContext.restore();
                            }

                            if (tmpObj.isPlayer && tmpObj.alive && tmpObj.sid !== undefined) {
                                const centerX = tmpObj.x - xOffset;
                                const centerY = tmpObj.y - yOffset;
                                mainContext.save();
                                mainContext.font = "bold 18px Hammersmith One";
                                mainContext.textAlign = "center";
                                mainContext.textBaseline = "middle";
                                mainContext.lineWidth = 6;
                                mainContext.strokeStyle = "#5a4516";
                                mainContext.strokeText(tmpObj.sid, centerX, centerY);
                                mainContext.fillStyle = "#fff";
                                mainContext.fillText(tmpObj.sid, centerX, centerY);
                                mainContext.restore();
                            }


                            if (tmpObj.health > 0) {
                                // HEALTH HOLDER:
                                var tmpWidth = config.healthBarWidth;
                                mainContext.fillStyle = darkOutlineColor;
                                mainContext.roundRect(tmpObj.x - xOffset - config.healthBarWidth - config.healthBarPad,
                                                      (tmpObj.y - yOffset + tmpObj.scale) + config.nameY, (config.healthBarWidth * 2) +
                                                      (config.healthBarPad * 2), 17, 8);
                                mainContext.fill();

                                // HEALTH BAR:
                                mainContext.fillStyle = (tmpObj == myPlayer || (tmpObj.team && tmpObj.team == myPlayer.team)) ? "#8ecc51" : "#cc5151";
                                mainContext.roundRect(tmpObj.x - xOffset - config.healthBarWidth,
                                                      (tmpObj.y - yOffset + tmpObj.scale) + config.nameY + config.healthBarPad,
                                                      ((config.healthBarWidth * 2) * (tmpObj.health / tmpObj.maxHealth)), 17 - config.healthBarPad * 2, 7);
                                mainContext.fill();

                                // RELOAD BARS  (Falcon 0.4.7's renderReloadingBars)
                                //
                                // Nothing is computed here. YoRHa already keeps
                                // primaryReload[sid] and secondaryReload[sid] as
                                // a 0..1 fraction — 1 means ready — because its
                                // own combat logic reads them every tick, and
                                // that fraction IS the bar. All Falcon had over
                                // YoRHa on this was the drawing.
                                //
                                // A bar is only up while its weapon is loading,
                                // so a player with both bars gone is a player
                                // who can swing right now.
                                if (visualOn("reloadBars") && tmpObj.isPlayer && tmpObj.alive) try {
                                    const reloadY = (tmpObj.y - yOffset + tmpObj.scale) + config.nameY - 20;
                                    const reloadW = config.healthBarWidth - config.healthBarPad;
                                    const reloadCentre = tmpObj.x - xOffset;

                                    const drawReloadBar = function (fraction, onLeft, colour) {
                                        if (typeof fraction != "number" || fraction >= 1) return;

                                        const x = onLeft ? reloadCentre - config.healthBarWidth - config.healthBarPad
                                                         : reloadCentre + config.healthBarPad;
                                        mainContext.fillStyle = darkOutlineColor;
                                        mainContext.roundRect(x, reloadY, reloadW + (config.healthBarPad * 2), 13, 6);
                                        mainContext.fill();
                                        mainContext.fillStyle = colour;
                                        mainContext.roundRect(x + config.healthBarPad, reloadY + config.healthBarPad,
                                                              reloadW * Math.max(0, fraction), 13 - (config.healthBarPad * 2), 5);
                                        mainContext.fill();
                                    };

                                    drawReloadBar(primaryReload[tmpObj.sid], true, "#d8a657");
                                    drawReloadBar(secondaryReload[tmpObj.sid], false, "#7daea3");
                                } catch (e) {}
                            }
                        }
                    }
                }
                // RENDER STUFF
                if (path && path.length > 0) {
                    drawMoveDirection();

                }



                // TO HERE

                // RENDER ANIM TEXTS:
                textManager.update(delta, mainContext, xOffset, yOffset);

                // RENDER CHAT MESSAGES:
                const chatPlayers = renderPlayerSource();
                for (var i = 0; i < chatPlayers.length; ++i) {
                    tmpObj = chatPlayers[i];
                    if (tmpObj.visible && tmpObj.chatCountdown > 0) {
                        tmpObj.chatCountdown -= delta;
                        if (tmpObj.chatCountdown <= 0)
                            tmpObj.chatCountdown = 0;
                        mainContext.font = "32px Hammersmith One";
                        var tmpSize = mainContext.measureText(tmpObj.chatMessage);
                        mainContext.textBaseline = "middle";
                        mainContext.textAlign = "center";
                        var tmpX = tmpObj.x - xOffset;
                        var tmpY = tmpObj.y - tmpObj.scale - yOffset - 90;
                        var tmpH = 47;
                        var tmpW = tmpSize.width + 17;
                        mainContext.fillStyle = "rgba(0,0,0,0.2)";
                        mainContext.roundRect(tmpX - tmpW / 2, tmpY - tmpH / 2, tmpW, tmpH, 6);
                        mainContext.fill();
                        mainContext.fillStyle = "#fff";
                        mainContext.fillText(tmpObj.chatMessage, tmpX, tmpY);
                    }
                }
            }

            // RENDER MINIMAP:
            renderMinimap(delta);

            // RENDER CONTROLS:
            if (controllingTouch.id !== -1) {
                renderControl(
                    controllingTouch.startX, controllingTouch.startY,
                    controllingTouch.currentX, controllingTouch.currentY
                );
            }
            if (attackingTouch.id !== -1) {
                renderControl(
                    attackingTouch.startX, attackingTouch.startY,
                    attackingTouch.currentX, attackingTouch.currentY
                );
            }
        }

        function renderEnemyTraps(xOffset, yOffset) {
            for (let i in predictEnemyTraps) {
                let object = predictEnemyTraps[i];

                mainContext.save();
                mainContext.translate(object.x - xOffset, object.y - yOffset);
                let image = getItemSprite({ id: object.id, name: items.list[object.id].name, scale: 40, predictEnemyTrap: true });
                mainContext.globalAlpha = .6;
                mainContext.drawImage(image, -(image.width / 2), -(image.height / 2));
                mainContext.restore();
            }
        }

        // RENDER CONTROL:
        function renderControl(startX, startY, currentX, currentY) {
            mainContext.save();
            mainContext.setTransform(1, 0, 0, 1, 0, 0);
            // mainContext.resetTransform();
            mainContext.scale(pixelDensity, pixelDensity);
            var controlRadius = 50;
            mainContext.beginPath();
            mainContext.arc(startX, startY, controlRadius, 0, Math.PI * 2, false);
            mainContext.closePath();
            mainContext.fillStyle = "rgba(255, 255, 255, 0.3)";
            mainContext.fill();
            var offsetX = currentX - startX;
            var offsetY = currentY - startY;
            var mag = Math.sqrt(Math.pow(offsetX, 2) + Math.pow(offsetY, 2));
            var divisor = mag > controlRadius ? (mag / controlRadius) : 1;
            offsetX /= divisor;
            offsetY /= divisor;
            mainContext.beginPath();
            mainContext.arc(startX + offsetX, startY + offsetY, controlRadius * 0.5, 0, Math.PI * 2, false);
            mainContext.closePath();
            mainContext.fillStyle = "white";
            mainContext.fill();
            mainContext.restore();
        }

        // RENDER PROJECTILES:
        function renderProjectiles(layer, xOffset, yOffset) {
            for (var i = 0; i < projectiles.length; ++i) {
                tmpObj = projectiles[i];
                if (tmpObj.active && tmpObj.layer == layer) {
                    tmpObj.update(delta);
                    if (tmpObj.active && isOnScreen(tmpObj.x - xOffset, tmpObj.y - yOffset, tmpObj.scale)) {
                        mainContext.save();
                        mainContext.translate(tmpObj.x - xOffset, tmpObj.y - yOffset);
                        mainContext.rotate(tmpObj.dir);
                        renderProjectile(0, 0, tmpObj, mainContext, 1);
                        mainContext.restore();
                    }
                }
            }
        }

        // RENDER PROJECTILE:
        var projectileSprites = {};
        function renderProjectile(x, y, obj, ctxt, debug) {
            if (obj.src) {
                var tmpSrc = items.projectiles[obj.indx].src;
                var tmpSprite = projectileSprites[tmpSrc];
                if (!tmpSprite) {
                    tmpSprite = new Image();
                    tmpSprite.onload = function () {
                        this.isLoaded = true;
                    }
                    tmpSprite.src = ".././img/weapons/" + tmpSrc + ".png";
                    projectileSprites[tmpSrc] = tmpSprite;
                }
                if (tmpSprite.isLoaded)
                    ctxt.drawImage(tmpSprite, x - (obj.scale / 2), y - (obj.scale / 2), obj.scale, obj.scale);
            } else if (obj.indx == 1) {
                ctxt.fillStyle = "#939393";
                renderCircle(x, y, obj.scale, ctxt);
            }
        }

        // RENDER WATER BODIES:
        function renderWaterBodies(xOffset, yOffset, ctxt, padding) {
            // MIDDLE RIVER:
            var tmpW = config.riverWidth + padding;
            var tmpY = (config.mapScale / 2) - yOffset - (tmpW / 2);
            if (tmpY < maxScreenHeight && tmpY + tmpW > 0) {
                ctxt.fillRect(0, tmpY, maxScreenWidth, tmpW);
            }
        }

        // RENDER GAME OBJECTS:
        function renderGameObjects(layer, xOffset, yOffset) {

            var tmpSprite, tmpX, tmpY;

            // ---- NEW: store spike positions ----
            let spikeList = [];

            const source = renderObjectSource();
            for (var i = 0; i < source.length; ++i) {
                tmpObj = source[i];

                if (tmpObj.active) {

                    tmpX = tmpObj.x + tmpObj.xWiggle - xOffset;
                    tmpY = tmpObj.y + tmpObj.yWiggle - yOffset;

                    // collect spikes (change name if needed later)
                    if (layer == 0 && tmpObj.isItem && tmpObj.name === "spikes") {
                        spikeList.push({x: tmpX, y: tmpY});
                    }

                    if (layer == 0) {
                        tmpObj.update(delta);
                    }

                    if (tmpObj.layer == layer && isOnScreen(tmpX, tmpY, tmpObj.scale + (tmpObj.blocker || 0))) {

                        mainContext.globalAlpha = tmpObj.hideFromEnemy ? 0.6 : 1;

                        if (tmpObj.isItem) {

                            // Enemy spikes and traps get the red wash, so the
                            // ground you can stand on is readable at a glance.
                            // Recomputed per frame rather than stamped once, so
                            // the toggle takes effect without a reload.
                            tmpObj.enemyBuilding = false;
                            try {
                                tmpObj.enemyBuilding = !!(visualOn("enemyBuildingTint") && myPlayer &&
                                                          (tmpObj.dmg || tmpObj.trap) && tmpObj.owner && !isObjectOur(tmpObj));
                            } catch (e) {}

                            tmpSprite = getItemSprite(tmpObj);

                            mainContext.save();
                            mainContext.translate(tmpX, tmpY);
                            mainContext.rotate(tmpObj.dir);
                            mainContext.drawImage(tmpSprite, -(tmpSprite.width / 2), -(tmpSprite.height / 2));

                            if (tmpObj.blocker) {
                                mainContext.strokeStyle = "#db6e6e";
                                mainContext.globalAlpha = 0.3;
                                mainContext.lineWidth = 6;
                                renderCircle(0, 0, tmpObj.blocker, mainContext, false, true);
                            }

                            mainContext.restore();

                        } else {
                            tmpSprite = getResSprite(tmpObj);
                            mainContext.drawImage(tmpSprite, tmpX - (tmpSprite.width / 2), tmpY - (tmpSprite.height / 2));
                        }
                    }
                }
            }
            if (layer == 0 && spikeList.length > 0) {

                mainContext.save();

                mainContext.shadowBlur = 0;
                mainContext.globalAlpha = 1;

                for (let i = 0; i < spikeList.length; i++) {

                    let sx = Math.round(spikeList[i].x);
                    let sy = Math.round(spikeList[i].y);

                    // main red dot (smaller)
                    mainContext.beginPath();
                    mainContext.fillStyle = "#ff1e1e";
                    mainContext.arc(sx, sy, 3.5, 0, Math.PI * 2);
                    mainContext.fill();

                    // darker inner center
                    mainContext.beginPath();
                    mainContext.fillStyle = "#8b0000";
                    mainContext.arc(sx, sy, 3, 0, Math.PI * 2);
                    mainContext.fill();
                }

                mainContext.restore();
            }
        }
        // GATHER ANIMATION:
        function gatherAnimation(sid, isObjectHit, weapon) {
            tmpObj = findPlayerBySID(sid);
            if (tmpObj) {
                hits.push({ player: tmpObj, isObjectHit: isObjectHit, weapon: weapon });

                if (isObjectHit) {
                    objectHits.push({ objects: damageObjects, player: tmpObj, weapon: weapon });
                    damageObjects = [];
                }

                tmpObj.startAnim(isObjectHit, weapon);
            }
        }

        // RENDER PLAYERS:
        function renderPlayers(xOffset, yOffset, zIndex) {
            mainContext.globalAlpha = 1;
            const list = renderPlayerSource();
            // Whichever body your mouse is actually aiming: yours normally, the
            // bot's while you are driving it.
            const aimed = (list === players) ? myPlayer : botViewSelf;
            for (var i = 0; i < list.length; ++i) {
                tmpObj = list[i];
                if (tmpObj.zIndex == zIndex) {
                    tmpObj.animate(delta);
                    if (tmpObj.visible) {
                        tmpObj.skinRot += (0.002 * delta);
                        tmpDir = ((tmpObj == aimed) ? getPossessAimDir(tmpObj) : tmpObj.dir) + tmpObj.dirPlus;
                        mainContext.save();
                        mainContext.translate(tmpObj.x - xOffset, tmpObj.y - yOffset);
                        // RENDER PLAYER:
                        mainContext.rotate(tmpDir);
                        renderPlayer(tmpObj, mainContext);
                        mainContext.restore();
                    }
                }
            }
        }

        // RENDER PLAYER:
        // =====================================================================
        // YoRHa VISUAL  —  the world reskinned to NieR:Automata's androids
        // =====================================================================
        // YoRHa Visual is an ATMOSPHERE-ONLY layer. It never repaints any
        // individual object (no recolored bodies, no tinted animals/hats, no
        // biome swaps), so every sprite keeps its true silhouette and every
        // hitbox reads exactly where it looks. The whole effect is a single
        // full-screen mood wash drawn in updateGame, gated by yorhaOn().
        function yorhaOn() { return !!(window.vars && window.vars.yorhaVisual); }

        // Read a toggle from inside the render loop.
        //
        // The loop starts at `doUpdate()` further down THIS bundle, which runs
        // synchronously — thousands of lines before `window.vars` is assigned
        // by the settings block at the bottom of the userscript. So the first
        // frame paints with window.vars still undefined, and a bare
        // `window.vars.something` there is a TypeError.
        //
        // That is not a dropped frame. doUpdate() calls updateGame() and only
        // then schedules the next frame, so a throw inside the render escapes
        // before requestAnimationFrame is ever reached: the loop never starts
        // again, and the canvas is left showing the one thing that did get
        // painted — the full-screen grass fill. A solid green screen.
        //
        // yorhaOn() above guards for exactly this reason. Anything else the
        // render path reads goes through here.
        function visualOn(name) { return !!(window.vars && window.vars[name]); }

        function renderPlayer(obj, ctxt) {
            ctxt = ctxt || mainContext;
            ctxt.lineWidth = outlineWidth;
            ctxt.lineJoin = "miter";
            var handAngle = (Math.PI / 4) * (items.weapons[obj.weaponIndex].armS || 1);
            var oHandAngle = (obj.buildIndex < 0) ? (items.weapons[obj.weaponIndex].hndS || 1) : 1;
            var oHandDist = (obj.buildIndex < 0) ? (items.weapons[obj.weaponIndex].hndD || 1) : 1;

            // TAIL/CAPE:
            if (obj.tailIndex > 0) {
                renderTail(obj.tailIndex, ctxt, obj);
            }

            // WEAPON BELLOW HANDS:
            if (obj.buildIndex < 0 && !items.weapons[obj.weaponIndex].aboveHand) {
                renderTool(items.weapons[obj.weaponIndex], config.weaponVariants[obj.weaponVariant].src, obj.scale, 0, ctxt);
                if (items.weapons[obj.weaponIndex].projectile != undefined && !items.weapons[obj.weaponIndex].hideProjectile) {
                    renderProjectile(obj.scale, 0,
                                     items.projectiles[items.weapons[obj.weaponIndex].projectile], mainContext);
                }
            }

            // HANDS:
            ctxt.fillStyle = config.skinColors[obj.skinColor];
            renderCircle(obj.scale * Math.cos(handAngle), (obj.scale * Math.sin(handAngle)), 14);
            renderCircle((obj.scale * oHandDist) * Math.cos(-handAngle * oHandAngle),
                         (obj.scale * oHandDist) * Math.sin(-handAngle * oHandAngle), 14);

            // WEAPON ABOVE HANDS:
            if (obj.buildIndex < 0 && items.weapons[obj.weaponIndex].aboveHand) {
                renderTool(items.weapons[obj.weaponIndex], config.weaponVariants[obj.weaponVariant].src, obj.scale, 0, ctxt);
                if (items.weapons[obj.weaponIndex].projectile != undefined && !items.weapons[obj.weaponIndex].hideProjectile) {
                    renderProjectile(obj.scale, 0,
                                     items.projectiles[items.weapons[obj.weaponIndex].projectile], mainContext);
                }
            }

            // BUILD ITEM:
            if (obj.buildIndex >= 0) {
                var tmpSprite = getItemSprite(items.list[obj.buildIndex]);
                ctxt.drawImage(tmpSprite, obj.scale - items.list[obj.buildIndex].holdOffset, -tmpSprite.width / 2);
            }

            // BODY:
            renderCircle(0, 0, obj.scale, ctxt);

            // SKIN:
            if (obj.skinIndex > 0) {
                ctxt.rotate(Math.PI / 2);
                renderSkin(obj.skinIndex, ctxt, null, obj);
            }
        }

        // RENDER SKINS:
        var skinSprites = {};
        var skinPointers = {};
        var tmpSkin;
        function renderSkin(index, ctxt, parentSkin, owner) {
            tmpSkin = skinSprites[index];
            if (!tmpSkin) {
                var tmpImage = new Image();
                tmpImage.onload = function () {
                    this.isLoaded = true;
                    this.onload = null;
                };
                tmpImage.src = ".././img/hats/hat_" + index + ".png";
                skinSprites[index] = tmpImage;
                tmpSkin = tmpImage;
            }
            var tmpObj = parentSkin || skinPointers[index];
            if (!tmpObj) {
                for (var i = 0; i < hats.length; ++i) {
                    if (hats[i].id == index) {
                        tmpObj = hats[i];
                        break;
                    }
                }
                skinPointers[index] = tmpObj;
            }
            if (tmpSkin.isLoaded)
                ctxt.drawImage(tmpSkin, -tmpObj.scale / 2, -tmpObj.scale / 2, tmpObj.scale, tmpObj.scale);
            if (!parentSkin && tmpObj.topSprite) {
                ctxt.save();
                ctxt.rotate(owner.skinRot);
                renderSkin(index + "_top", ctxt, tmpObj, owner);
                ctxt.restore();
            }
        }

        // RENDER TAIL:
        var accessSprites = {};
        var accessPointers = {};
        function renderTail(index, ctxt, owner) {
            tmpSkin = accessSprites[index];
            if (!tmpSkin) {
                var tmpImage = new Image();
                tmpImage.onload = function () {
                    this.isLoaded = true;
                    this.onload = null;
                };
                tmpImage.src = ".././img/accessories/access_" + index + ".png";
                accessSprites[index] = tmpImage;
                tmpSkin = tmpImage;
            }
            var tmpObj = accessPointers[index];
            if (!tmpObj) {
                for (var i = 0; i < accessories.length; ++i) {
                    if (accessories[i].id == index) {
                        tmpObj = accessories[i];
                        break;
                    }
                }
                accessPointers[index] = tmpObj;
            }
            if (tmpSkin.isLoaded) {
                ctxt.save();
                ctxt.translate(-20 - (tmpObj.xOff || 0), 0);
                if (tmpObj.spin)
                    ctxt.rotate(owner.skinRot);
                ctxt.drawImage(tmpSkin, -(tmpObj.scale / 2), -(tmpObj.scale / 2), tmpObj.scale, tmpObj.scale);
                ctxt.restore();
            }
        }

        // RENDER TOOL:
        var toolSprites = {};
        function renderTool(obj, variant, x, y, ctxt) {
            var tmpSrc = obj.src + (variant || "");
            var tmpSprite = toolSprites[tmpSrc];
            if (!tmpSprite) {
                tmpSprite = new Image();
                tmpSprite.onload = function () {
                    this.isLoaded = true;
                }
                tmpSprite.src = ".././img/weapons/" + tmpSrc + ".png";
                toolSprites[tmpSrc] = tmpSprite;
            }
            if (tmpSprite.isLoaded)
                ctxt.drawImage(tmpSprite, x + obj.xOff - (obj.length / 2), y + obj.yOff - (obj.width / 2), obj.length, obj.width);
        }

        // Call this in your tree rendering loop, BEFORE rendering the tree itself
        // Example usage:
        /*
for (let tree of trees) {
    renderTreeShadow(tree, tmpContext, xOffset, yOffset);
    // Then render the actual tree
    renderTree(tree, tmpContext, xOffset, yOffset);
}
*/
        // RENDER GAME OBJECTS:
        var gameObjectSprites = {};
        function getResSprite(obj) {
            var biomeID = (obj.y >= config.mapScale - config.snowBiomeTop) ? 2 : ((obj.y <= config.snowBiomeTop) ? 1 : 0);
            var tmpIndex = (obj.type + "_" + obj.scale + "_" + biomeID);
            var tmpSprite = gameObjectSprites[tmpIndex];
            if (!tmpSprite) {
                var tmpCanvas = document.createElement('canvas');
                tmpCanvas.width = tmpCanvas.height = (obj.scale * 2.1) + outlineWidth;
                var tmpContext = tmpCanvas.getContext('2d');
                tmpContext.translate((tmpCanvas.width / 2), (tmpCanvas.height / 2));
                tmpContext.rotate(UTILS.randFloat(0, Math.PI));
                tmpContext.strokeStyle = outlineColor;
                tmpContext.lineWidth = outlineWidth;
                let colors = [
                    ["#b1d959", "#95b946"],
                    ["#bade6e", "#aac76b"],
                    ["#a7d544", "#86a63f"],
                    ["#b4db62", "#9ebf57"]
                ]
                let select = colors[Math.floor(Math.random() * colors.length)];
                if (obj.type == 0) {
                    var tmpScale;
                    for (var i = 0; i < 2; ++i) {
                        tmpScale = tmpObj.scale * (!i ? 1 : 0.5);
                        renderStar(tmpContext, 7, tmpScale, tmpScale * 0.7);
                        tmpContext.fillStyle = !biomeID ? (!i ? "#9ebf57" : "#b4db62") : (!i ? "#e3f1f4" : "#fff");
                        tmpContext.fill();
                        if (!i)
                            tmpContext.stroke();
                    }
                } else if (obj.type == 1) {
                    if (biomeID == 2) {
                        tmpContext.fillStyle = "#606060";
                        renderStar(tmpContext, 6, obj.scale * 0.3, obj.scale * 0.71);
                        tmpContext.fill();
                        tmpContext.stroke();
                        tmpContext.fillStyle = "#89a54c";
                        renderCircle(0, 0, obj.scale * 0.55, tmpContext);
                        tmpContext.fillStyle = "#a5c65b";
                        renderCircle(0, 0, obj.scale * 0.3, tmpContext, true);
                    } else {
                        renderBlob(tmpContext, 6, tmpObj.scale, tmpObj.scale * 0.7);
                        tmpContext.fillStyle = biomeID ? "#e3f1f4" : "#89a54c";
                        tmpContext.fill();
                        tmpContext.stroke();
                        tmpContext.fillStyle = biomeID ? "#6a64af" : "#c15555";
                        var tmpRange;
                        var berries = 4;
                        var rotVal = mathPI2 / berries;
                        for (var i = 0; i < berries; ++i) {
                            tmpRange = UTILS.randInt(tmpObj.scale / 3.5, tmpObj.scale / 2.3);
                            renderCircle(tmpRange * Math.cos(rotVal * i), tmpRange * Math.sin(rotVal * i),
                                         UTILS.randInt(10, 12), tmpContext);
                        }
                    }
                } else if (obj.type == 2 || obj.type == 3) {
                    tmpContext.fillStyle = (obj.type == 2) ? (biomeID == 2 ? "#938d77" : "#939393") : "#e0c655";
                    renderStar(tmpContext, 3, obj.scale, obj.scale);
                    tmpContext.fill();
                    tmpContext.stroke();
                    tmpContext.fillStyle = (obj.type == 2) ? (biomeID == 2 ? "#b2ab90" : "#bcbcbc") : "#ebdca3";
                    renderStar(tmpContext, 3, obj.scale * 0.55, obj.scale * 0.65);
                    tmpContext.fill();
                }
                tmpSprite = tmpCanvas;
                gameObjectSprites[tmpIndex] = tmpSprite;
            }
            return tmpSprite;
        }
        // RENDER HEALTH CIRCLE:
        function renderHealthCircle(x, y, scale, tmpContext, dontStroke, dontFill) {
            tmpContext = tmpContext || mainContext;
            tmpContext.beginPath();
            tmpContext.arc(x, y, scale, 0, 2 * Math.PI);
            if (!dontFill) tmpContext.fill();
            if (!dontStroke) tmpContext.stroke();
        }
        // GET ITEM SPRITE:
        var itemSprites = [];

        // One cache slot per way an item can be drawn. `enemyBuilding` is the
        // Falcon red wash below, and it needs its own slot or the first spike
        // drawn would decide the colour of every spike on the map.
        function itemSpriteKey(obj) {
            return obj.id +
                (obj.predictEnemyTrap ? 100 : (obj.prediction ? (obj.preplace ? 200 : 300) : 0)) +
                (obj.enemyBuilding ? 400 : 0);
        }

        function getItemSprite(obj, asIcon) {
            var tmpSprite = itemSprites[itemSpriteKey(obj)];
            if (!tmpSprite || asIcon) {
                var tmpCanvas = document.createElement('canvas');
                tmpCanvas.width = tmpCanvas.height = (obj.scale * 2.5) + outlineWidth +
                    (items.list[obj.id].spritePadding || 0);
                var tmpContext = tmpCanvas.getContext('2d');
                tmpContext.translate((tmpCanvas.width / 2), (tmpCanvas.height / 2));
                tmpContext.rotate(asIcon ? 0 : (Math.PI / 2));
                tmpContext.strokeStyle = obj.prediction ? obj.preplace ? "#00FFFF" : "#00FFFF" : outlineColor;
                tmpContext.lineWidth = outlineWidth * (asIcon ? (tmpCanvas.width / 81) : 1);
                if (obj.name == "apple") {
                    tmpContext.fillStyle = "#c15555";
                    renderCircle(0, 0, obj.scale, tmpContext);
                    tmpContext.fillStyle = "#89a54c";
                    var leafDir = -(Math.PI / 2);
                    renderLeaf(obj.scale * Math.cos(leafDir), obj.scale * Math.sin(leafDir),
                               25, leafDir + Math.PI / 2, tmpContext);
                } else if (obj.name == "cookie") {
                    tmpContext.fillStyle = "#cca861";
                    renderCircle(0, 0, obj.scale, tmpContext);
                    tmpContext.fillStyle = "#937c4b";
                    var chips = 4;
                    var rotVal = mathPI2 / chips;
                    var tmpRange;
                    for (var i = 0; i < chips; ++i) {
                        tmpRange = UTILS.randInt(obj.scale / 2.5, obj.scale / 1.7);
                        renderCircle(tmpRange * Math.cos(rotVal * i), tmpRange * Math.sin(rotVal * i),
                                     UTILS.randInt(4, 5), tmpContext, true);
                    }
                } else if (obj.name == "cheese") {
                    tmpContext.fillStyle = "#f4f3ac";
                    renderCircle(0, 0, obj.scale, tmpContext);
                    tmpContext.fillStyle = "#c3c28b";
                    var chips = 4;
                    var rotVal = mathPI2 / chips;
                    var tmpRange;
                    for (var i = 0; i < chips; ++i) {
                        tmpRange = UTILS.randInt(obj.scale / 2.5, obj.scale / 1.7);
                        renderCircle(tmpRange * Math.cos(rotVal * i), tmpRange * Math.sin(rotVal * i),
                                     UTILS.randInt(4, 5), tmpContext, true);
                    }
                } else if (obj.name == "wood wall" || obj.name == "stone wall" || obj.name == "castle wall") {
                    tmpContext.fillStyle = (obj.name == "castle wall") ? "#83898e" : (obj.name == "wood wall") ?
                        "#a5974c" : "#939393";
                    var sides = (obj.name == "castle wall") ? 4 : 3;
                    renderStar(tmpContext, sides, obj.scale * 1.1, obj.scale * 1.1);
                    tmpContext.fill();
                    tmpContext.stroke();
                    tmpContext.fillStyle = (obj.name == "castle wall") ? "#9da4aa" : (obj.name == "wood wall") ?
                        "#c9b758" : "#bcbcbc";
                    renderStar(tmpContext, sides, obj.scale * 0.65, obj.scale * 0.65);
                    tmpContext.fill();
                } else if (obj.name == "spikes" || obj.name == "greater spikes" || obj.name == "poison spikes" || obj.name == "spinning spikes") {
                    var tmpScale = (obj.scale * 0.6);

                    if (obj.prediction) {
                        // Prediction mode: render as circle
                        tmpContext.fillStyle = obj.preplace ? "#00FFFF" : "#00FFFF";
                        tmpContext.globalAlpha = 0.6;
                        renderHealthCircle(0, 0, obj.scale * 1.0, tmpContext, false, true);
                        tmpContext.fill();
                        tmpContext.globalAlpha = 1;
                    } else {
                        // Normal mode: render as star
                        tmpContext.fillStyle = (obj.name == "poison spikes") ? "#7b935d" : "#939393";
                        renderStar(tmpContext, (obj.name == "spikes") ? 5 : 6, obj.scale, tmpScale);
                        tmpContext.fill();
                        tmpContext.stroke();
                    }

                    tmpContext.fillStyle = "#a5974c";
                    renderStar(tmpContext, (obj.name == "spikes") ? 5 : 6, obj.scale, tmpScale);

                    obj.prediction && (
                        tmpContext.globalAlpha = 0.6,
                        tmpContext.fillStyle = obj.preplace ? "#00FFFF" : "#00FFFF",
                        renderStar(tmpContext, (obj.name == "spikes") ? 5 : 6, obj.scale, tmpScale),
                        tmpContext.globalAlpha = 1);

                    tmpContext.fillStyle = "#c9b758";
                    renderStar(tmpContext, (obj.name == "spikes") ? 5 : 6, obj.scale, tmpScale);

                    obj.prediction && (
                        tmpContext.globalAlpha = 0.6,
                        tmpContext.fillStyle = obj.preplace ? "#00FFFF" : "#00FFFF",
                        renderStar(tmpContext, (obj.name == "spikes") ? 5 : 6, obj.scale, tmpScale),
                        tmpContext.globalAlpha = 1);
                } else if (obj.name == "windmill" || obj.name == "faster windmill" || obj.name == "power mill") {
                    tmpContext.fillStyle = "#a5974c";
                    renderCircle(0, 0, obj.scale, tmpContext);

                    obj.prediction && (
                        tmpContext.globalAlpha = 0.6,
                        tmpContext.fillStyle = obj.preplace ? "#00FFFF" : "#00FFFF",
                        renderCircle(0, 0, obj.scale, tmpContext),
                        tmpContext.globalAlpha = 1);

                    tmpContext.fillStyle = "#c9b758";
                    renderRectCircle(0, 0, obj.scale * 1.5, 29, 4, tmpContext);

                    obj.prediction && (
                        tmpContext.globalAlpha = 0.6,
                        tmpContext.fillStyle = obj.preplace ? "#00FFFF" : "#00FFFF",
                        renderRectCircle(0, 0, obj.scale * 1.5, 29, 4, tmpContext),
                        tmpContext.globalAlpha = 1);

                    tmpContext.fillStyle = "#a5974c";
                    renderCircle(0, 0, obj.scale * 0.5, tmpContext);

                    obj.prediction && (
                        tmpContext.globalAlpha = 0.6,
                        tmpContext.fillStyle = obj.preplace ? "#00FFFF" : "#00FFFF",
                        renderHealthCircle(0, 0, obj.scale * 1.0, tmpContext, false, true),
                        tmpContext.globalAlpha = 1);
                } else if (obj.name == "mine") {
                    tmpContext.fillStyle = "#939393";
                    renderStar(tmpContext, 3, obj.scale, obj.scale);
                    tmpContext.fill();
                    tmpContext.stroke();
                    tmpContext.fillStyle = "#bcbcbc";
                    renderStar(tmpContext, 3, obj.scale * 0.55, obj.scale * 0.65);
                    tmpContext.fill();
                } else if (obj.name == "sapling") {
                    for (var i = 0; i < 2; ++i) {
                        var tmpScale = obj.scale * (!i ? 1 : 0.5);
                        renderStar(tmpContext, 7, tmpScale, tmpScale * 0.7);
                        tmpContext.fillStyle = (!i ? "#9ebf57" : "#b4db62");
                        tmpContext.fill();
                        if (!i) tmpContext.stroke();
                    }
                } else if (obj.name == "pit trap") {

                    if (obj.prediction) {
                        // Prediction mode: render as circle
                        tmpContext.fillStyle = obj.preplace ? "#00FFFF" : "#00FFFF";
                        tmpContext.globalAlpha = 0.6;
                        renderHealthCircle(0, 0, obj.scale * 1.0, tmpContext, false, true);
                        tmpContext.fill();
                        tmpContext.globalAlpha = 1;
                    } else {
                        // Normal mode: default pit trap colors
                        tmpContext.fillStyle = "#8B4513";
                        tmpContext.strokeStyle = "#654321";
                        tmpContext.lineWidth = 2;
                        renderStar(tmpContext, 5, obj.scale, tmpScale);
                        tmpContext.fill();
                        tmpContext.stroke();
                    }

                    tmpContext.fillStyle = "#A0522D";
                    renderStar(tmpContext, 5, obj.scale, tmpScale);
                    tmpContext.fill();

                    obj.prediction && (
                        tmpContext.globalAlpha = 0.6,
                        tmpContext.fillStyle = obj.preplace ? "#00FFFF" : "#00FFFF",
                        renderStar(tmpContext, 5, obj.scale, tmpScale),
                        tmpContext.fill(),
                        tmpContext.globalAlpha = 1);

                    tmpContext.fillStyle = "#00FFFF";
                    renderStar(tmpContext, 5, obj.scale, tmpScale);
                    tmpContext.fill();

                    obj.prediction && (
                        tmpContext.globalAlpha = 0.6,
                        tmpContext.fillStyle = obj.preplace ? "#00FFFF" : "#00FFFF",
                        renderStar(tmpContext, 5, obj.scale, tmpScale),
                        tmpContext.fill(),
                        tmpContext.globalAlpha = 1);
                } else if (obj.name == "boost pad") {
                    tmpContext.fillStyle = "#7e7f82";
                    renderRect(0, 0, obj.scale * 2, obj.scale * 2, tmpContext);
                    tmpContext.fill();
                    tmpContext.stroke();
                    tmpContext.fillStyle = "#dbd97d";
                    renderTriangle(obj.scale * 1, tmpContext);
                } else if (obj.name == "turret") {
                    tmpContext.fillStyle = "#a5974c";
                    renderCircle(0, 0, obj.scale, tmpContext);
                    tmpContext.fill();
                    tmpContext.stroke();
                    tmpContext.fillStyle = "#939393";
                    var tmpLen = 50;
                    renderRect(0, -tmpLen / 2, obj.scale * 0.9, tmpLen, tmpContext);
                    renderCircle(0, 0, obj.scale * 0.6, tmpContext);
                    tmpContext.fill();
                    tmpContext.stroke();
                } else if (obj.name == "platform") {
                    tmpContext.fillStyle = "#cebd5f";
                    var tmpCount = 4;
                    var tmpS = obj.scale * 2;
                    var tmpW = tmpS / tmpCount;
                    var tmpX = -(obj.scale / 2);
                    for (var i = 0; i < tmpCount; ++i) {
                        renderRect(tmpX - (tmpW / 2), 0, tmpW, obj.scale * 2, tmpContext);
                        tmpContext.fill();
                        tmpContext.stroke();
                        tmpX += tmpS / tmpCount;
                    }
                } else if (obj.name == "healing pad") {
                    tmpContext.fillStyle = "#7e7f82";
                    renderRect(0, 0, obj.scale * 2, obj.scale * 2, tmpContext);
                    tmpContext.fill();
                    tmpContext.stroke();
                    tmpContext.fillStyle = "#db6e6e";
                    renderRectCircle(0, 0, obj.scale * 0.65, 20, 4, tmpContext, true);
                } else if (obj.name == "spawn pad") {
                    tmpContext.fillStyle = "#7e7f82";
                    renderRect(0, 0, obj.scale * 2, obj.scale * 2, tmpContext);
                    tmpContext.fill();
                    tmpContext.stroke();
                    tmpContext.fillStyle = "#71aad6";
                    renderCircle(0, 0, obj.scale * 0.6, tmpContext);
                } else if (obj.name == "blocker") {
                    tmpContext.fillStyle = "#7e7f82";
                    renderCircle(0, 0, obj.scale, tmpContext);
                    tmpContext.fill();
                    tmpContext.stroke();
                    tmpContext.rotate(Math.PI / 4);
                    tmpContext.fillStyle = "#db6e6e";
                    renderRectCircle(0, 0, obj.scale * 0.65, 20, 4, tmpContext, true);
                } else if (obj.name == "teleporter") {
                    tmpContext.fillStyle = "#7e7f82";
                    renderCircle(0, 0, obj.scale, tmpContext);
                    tmpContext.fill();
                    tmpContext.stroke();
                    tmpContext.rotate(Math.PI / 4);
                    tmpContext.fillStyle = "#d76edb";
                    renderCircle(0, 0, obj.scale * 0.5, tmpContext, true);
                }
                // ENEMY BUILDING TINT  (Falcon 0.4.7's renderRedOverlay)
                //
                // Falcon washes the shape in dark red by re-filling the current
                // path, which only works while the last shape drawn happens to
                // be the silhouette. Compositing source-atop over the finished
                // canvas is the same wash without that assumption: it paints
                // exactly the pixels already drawn, outline included, whatever
                // the branch above ended on. The transform is reset first
                // because the branches rotate and translate as they go.
                if (obj.enemyBuilding) {
                    tmpContext.setTransform(1, 0, 0, 1, 0, 0);
                    tmpContext.globalCompositeOperation = "source-atop";
                    tmpContext.globalAlpha = 0.55;
                    tmpContext.fillStyle = "#780c0c";
                    tmpContext.fillRect(0, 0, tmpCanvas.width, tmpCanvas.height);
                    tmpContext.globalAlpha = 1;
                    tmpContext.globalCompositeOperation = "source-over";
                }

                tmpSprite = tmpCanvas;
                if (!asIcon)
                    itemSprites[itemSpriteKey(obj)] = tmpSprite;
            }
            return tmpSprite;
        }

        // RENDER LEAF:
        function renderLeaf(x, y, l, r, ctxt) {
            var endX = x + (l * Math.cos(r));
            var endY = y + (l * Math.sin(r));
            var width = l * 0.4;
            ctxt.moveTo(x, y);
            ctxt.beginPath();
            ctxt.quadraticCurveTo(((x + endX) / 2) + (width * Math.cos(r + Math.PI / 2)),
                                  ((y + endY) / 2) + (width * Math.sin(r + Math.PI / 2)), endX, endY);
            ctxt.quadraticCurveTo(((x + endX) / 2) - (width * Math.cos(r + Math.PI / 2)),
                                  ((y + endY) / 2) - (width * Math.sin(r + Math.PI / 2)), x, y);
            ctxt.closePath();
            ctxt.fill();
            ctxt.stroke();
        }

        // RENDER CIRCLE:
        function renderCircle(x, y, scale, tmpContext, dontStroke, dontFill) {
            tmpContext = tmpContext || mainContext;
            tmpContext.beginPath();
            tmpContext.arc(x, y, scale, 0, 2 * Math.PI);
            if (!dontFill) tmpContext.fill();
            if (!dontStroke) tmpContext.stroke();
        }

        // RENDER STAR SHAPE:
        function renderStar(ctxt, spikes, outer, inner) {
            var rot = Math.PI / 2 * 3;
            var x, y;
            var step = Math.PI / spikes;
            ctxt.beginPath();
            ctxt.moveTo(0, -outer);
            for (var i = 0; i < spikes; i++) {
                x = Math.cos(rot) * outer;
                y = Math.sin(rot) * outer;
                ctxt.lineTo(x, y);
                rot += step;
                x = Math.cos(rot) * inner;
                y = Math.sin(rot) * inner;
                ctxt.lineTo(x, y);
                rot += step;
            }
            ctxt.lineTo(0, -outer);
            ctxt.closePath();
        }

        // RENDER RECTANGLE:
        function renderRect(x, y, w, h, ctxt, stroke) {
            ctxt.fillRect(x - (w / 2), y - (h / 2), w, h);
            if (!stroke)
                ctxt.strokeRect(x - (w / 2), y - (h / 2), w, h);
        }

        // RENDER RECTCIRCLE:
        function renderRectCircle(x, y, s, sw, seg, ctxt, stroke) {
            ctxt.save();
            ctxt.translate(x, y);
            seg = Math.ceil(seg / 2);
            for (var i = 0; i < seg; i++) {
                renderRect(0, 0, s * 2, sw, ctxt, stroke);
                ctxt.rotate(Math.PI / seg);
            }
            ctxt.restore();
        }

        // RENDER BLOB:
        function renderBlob(ctxt, spikes, outer, inner) {
            var rot = Math.PI / 2 * 3;
            var x, y;
            var step = Math.PI / spikes;
            var tmpOuter;
            ctxt.beginPath();
            ctxt.moveTo(0, -inner);
            for (var i = 0; i < spikes; i++) {
                tmpOuter = UTILS.randInt(outer + 0.9, outer * 1.2);
                ctxt.quadraticCurveTo(Math.cos(rot + step) * tmpOuter, Math.sin(rot + step) * tmpOuter,
                                      Math.cos(rot + (step * 2)) * inner, Math.sin(rot + (step * 2)) * inner);
                rot += step * 2;
            }
            ctxt.lineTo(0, -inner);
            ctxt.closePath();
        }

        // RENDER TRIANGLE:
        function renderTriangle(s, ctx) {
            ctx = ctx || mainContext;
            var h = s * (Math.sqrt(3) / 2);
            ctx.beginPath();
            ctx.moveTo(0, -h / 2);
            ctx.lineTo(-s / 2, h / 2);
            ctx.lineTo(s / 2, h / 2);
            ctx.lineTo(0, -h / 2);
            ctx.fill();
            ctx.closePath();
        }

